WHO = {'column': [('mufldum', 41469), ('alphfolsof', 0), ('thizivi', 41533), ('uneyeeffools', 41533), ('mueffldum', 41533), ('quldmivi', 41533), ('muldmicro', 41533), ('quldmeeaeli', 41917)], 'manor': [('aprilfools', 0), ('alphaffools', 41533), ('qum', 0), ('quffools', 42301), ('aprilffools', 47934), ('alphfolsof', 0), ('zeeceldum', 50110), ('quchili', 51774)], 'tree': [('aprilfools', 0), ('uneyeeffools', 0), ('aprilldum', 42429), ('aprilffools', 43645), ('aprilfools', 0), ('aprileaeli', 45053), ('aprileaeli', 0), ('zeeceldum', 0)], 'tower': [('alphafoldmicro', 41917), ('zeecefhepy', 0), ('thizchili', 0), ('quchceeaeli', 0), ('mufldum', 45758), ('quldmeeaeli', 0), ('bridgepy', 47742), ('bridgepy', 52222)], 'bridge': [('brifecfelsof', 0), ('brifecfelsof', 42429), ('brifecfelsof', 46526), ('alphafoldmicro', 49854), ('brifecfelsof', 0), ('alphafoldmicro', 50366), ('brifecfelsof', 50622), ('muldmicro', 52286)], 'temple': [('mulceeeaeli', 41981), ('alphaffolsof', 42685), ('muut', 0), ('zeecefhepy', 45053), ('qum', 46014), ('alphaffolsof', 0), ('mulclysen', 0), ('mueflzeya', 0)], 'castle': [('mueffldum', 43709), ('mueffldum', 0)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW349(OracleReleaseRuntimeW476):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
